#!/usr/bin/env node
'use strict';

const path = require('node:path');
const {
  TODOS_FILE_NAME,
  TodoError,
  loadTodos,
  saveTodos,
  parseId,
  addTodo,
  completeTodo,
  deleteTodo,
  formatList,
} = require('./lib/todos');

const COMMAND_USAGE = {
  add: 'node index.js add "<text>"',
  list: 'node index.js list',
  complete: 'node index.js complete <id>',
  delete: 'node index.js delete <id>',
};

const HELP = `Usage: node index.js <command> [arguments]

Commands:
  add "<text>"    Add a new todo
  list            List all todos
  complete <id>   Mark a todo as done
  delete <id>     Delete a todo
  help            Show this help

Todos are stored in ${TODOS_FILE_NAME} in the current directory.`;

function usageFor(command) {
  return { usage: `Usage: ${COMMAND_USAGE[command]}` };
}

function requireId(args, command) {
  if (args.length === 0) throw new TodoError('Missing todo id', usageFor(command));
  if (args.length > 1) {
    throw new TodoError(`Expected one todo id, got ${args.length} arguments`, usageFor(command));
  }
  return parseId(args[0]);
}

/**
 * Runs the CLI with `argv` (arguments after the script name) and returns the exit code.
 * Output streams and working directory are injectable for testing.
 */
function run(argv, { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr } = {}) {
  const [command, ...args] = argv;
  const file = path.join(cwd, TODOS_FILE_NAME);
  const print = (message) => stdout.write(`${message}\n`);

  try {
    switch (command) {
      case 'add': {
        if (args.length === 0) throw new TodoError('Missing todo text', usageFor('add'));
        const todos = loadTodos(file);
        // Accept unquoted multi-word text: `add Buy groceries` is the same as `add "Buy groceries"`.
        const todo = addTodo(todos, args.join(' '));
        saveTodos(file, todos);
        print(`Added todo #${todo.id}: ${todo.text}`);
        return 0;
      }

      case 'list':
        print(formatList(loadTodos(file)));
        return 0;

      case 'complete': {
        const id = requireId(args, 'complete');
        const todos = loadTodos(file);
        const { todo, alreadyCompleted } = completeTodo(todos, id);
        if (alreadyCompleted) {
          print(`Todo #${id} is already completed: ${todo.text}`);
          return 0;
        }
        saveTodos(file, todos);
        print(`Completed todo #${id}: ${todo.text}`);
        return 0;
      }

      case 'delete': {
        const id = requireId(args, 'delete');
        const todos = loadTodos(file);
        const todo = deleteTodo(todos, id);
        saveTodos(file, todos);
        print(`Deleted todo #${id}: ${todo.text}`);
        return 0;
      }

      case 'help':
      case '--help':
      case '-h':
        print(HELP);
        return 0;

      case undefined:
        stderr.write(`${HELP}\n`);
        return 1;

      default:
        throw new TodoError(`Unknown command "${command}"`, { usage: HELP });
    }
  } catch (err) {
    stderr.write(`Error: ${err.message}\n`);
    if (err.usage) stderr.write(`${err.usage}\n`);
    return 1;
  }
}

if (require.main === module) {
  process.exitCode = run(process.argv.slice(2));
}

module.exports = { run };

