    assert.throws(() => loadTodos(file), { name: 'TodoError', message: /JSON array/ });
  });

  for (const [label, entry] of [
    ['null', null],
    ['a string', 'Buy milk'],
    ['a missing id', { text: 'a', completed: false }],
    ['a non-integer id', { id: 1.5, text: 'a', completed: false }],
    ['a zero id', { id: 0, text: 'a', completed: false }],
    ['non-string text', { id: 1, text: 42, completed: false }],
    ['non-boolean completed', { id: 1, text: 'a', completed: 'yes' }],
  ]) {
