    fs.mkdirSync(file); // reading a directory fails with EISDIR, not ENOENT
    assert.throws(() => loadTodos(file), (err) => !(err instanceof TodoError) && err.code === 'EISDIR');
  });
});

describe('parseId', () => {
  it('parses positive integers', () => {
    assert.equal(parseId('1'), 1);
    assert.equal(parseId('42'), 42);
    assert.equal(parseId('007'), 7);
  });

  for (const value of ['abc', '', ' 1', '1 ', '1.5', '-1', '0', '1e3', '0x1', '+1', '99999999999999999999']) {
    it(`rejects ${JSON.stringify(value)}`, () => {
      assert.throws(() => parseId(value), { name: 'TodoError', message: /Invalid id/ });
