  it('creates a pending todo with id 1 in an empty list', () => {
    const todos = [];
    const now = new Date('2026-09-30T12:34:56.789Z');
    const added = addTodo(todos, 'Buy groceries', now);
    assert.deepEqual(added, {
      id: 1,
