      assert.throws(() => addTodo(todos, text), { name: 'TodoError', message: /cannot be empty/ });
    }
    assert.deepEqual(todos, [todo(1, 'a')]);
  });
});

describe('completeTodo', () => {
  it('marks a pending todo as completed', () => {
    const todos = [todo(1, 'a'), todo(2, 'b')];
    const result = completeTodo(todos, 2);
    assert.equal(result.alreadyCompleted, false);
