    assert.equal(result.alreadyCompleted, true);
    assert.equal(todos[0].completed, true);
  });

  it('throws a TodoError for an unknown id', () => {
    assert.throws(() => completeTodo([todo(1, 'a')], 5), { name: 'TodoError', message: 'No todo with id 5' });
    assert.throws(() => completeTodo([], 1), TodoError);
  });
});

describe('deleteTodo', () => {
  it('removes and returns the todo, leaving others untouched', () => {
    const todos = [todo(1, 'a'), todo(2, 'b'), todo(3, 'c')];
    const removed = deleteTodo(todos, 2);
    assert.deepEqual(removed, todo(2, 'b'));
    assert.deepEqual(todos, [todo(1, 'a'), todo(3, 'c')]);
  });

  it('throws a TodoError for an unknown id without modifying the list', () => {
    const todos = [todo(1, 'a')];
    assert.throws(() => deleteTodo(todos, 2), { name: 'TodoError', message: 'No todo with id 2' });
    assert.deepEqual(todos, [todo(1, 'a')]);
  });
});

describe('formatList', () => {
  it('shows a helpful message for an empty list', () => {
    assert.match(formatList([]), /No todos yet/);
  });

  it('shows id, status indicator, and text for each todo', () => {
    assert.equal(
      formatList([todo(1, 'Buy groceries'), todo(2, 'Walk the dog', true)]),
      '1. [ ] Buy groceries\n2. [x] Walk the dog',
    );
  });

  it('right-aligns ids so the status column lines up', () => {
    assert.equal(formatList([todo(9, 'a'), todo(10, 'b', true)]), ' 9. [ ] a\n10. [x] b');
  });
});

