'use strict';

// End-to-end tests: each test runs the real CLI as a child process in a fresh temp directory.

const { describe, it, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const CLI = path.join(__dirname, '..', 'index.js');

let cwd;
let todosFile;

function todo(...args) {
  const result = spawnSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

function readTodos() {
  return JSON.parse(fs.readFileSync(todosFile, 'utf8'));
}

function writeTodos(todos) {
  fs.writeFileSync(todosFile, JSON.stringify(todos));
}

/** Asserts the command failed with an error mentioning `pattern` and left todos.json unchanged. */
function assertFailsWithoutChanges(args, pattern) {
  const before = fs.existsSync(todosFile) ? fs.readFileSync(todosFile, 'utf8') : null;
  const result = todo(...args);
  assert.equal(result.code, 1, `expected exit code 1, got ${result.code}`);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /^Error: /);
  assert.match(result.stderr, pattern);
  const after = fs.existsSync(todosFile) ? fs.readFileSync(todosFile, 'utf8') : null;
  assert.equal(after, before, 'todos.json should not change on error');
}

beforeEach(() => {
  cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'todo-cli-'));
  todosFile = path.join(cwd, 'todos.json');
});

afterEach(() => {
  fs.rmSync(cwd, { recursive: true, force: true });
});

describe('add', () => {
  it('adds a todo and stores it in todos.json in the current directory', () => {
    const result = todo('add', 'Buy groceries');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Added todo #1: Buy groceries\n');
    assert.equal(result.stderr, '');

    const todos = readTodos();
    assert.equal(todos.length, 1);
    assert.deepEqual(Object.keys(todos[0]).sort(), ['completed', 'createdAt', 'id', 'text']);
    assert.equal(todos[0].id, 1);
    assert.equal(todos[0].text, 'Buy groceries');
    assert.equal(todos[0].completed, false);
    assert.equal(new Date(todos[0].createdAt).toISOString(), todos[0].createdAt);
  });

  it('does not write todos.json next to the script', () => {
    todo('add', 'x');
    assert.ok(fs.existsSync(todosFile));
    assert.ok(!fs.existsSync(path.join(path.dirname(CLI), 'todos.json')) || path.dirname(CLI) === cwd);
  });

  it('auto-increments ids across invocations', () => {
    assert.equal(todo('add', 'one').stdout, 'Added todo #1: one\n');
    assert.equal(todo('add', 'two').stdout, 'Added todo #2: two\n');
    assert.equal(todo('add', 'three').stdout, 'Added todo #3: three\n');
    assert.deepEqual(readTodos().map((t) => t.id), [1, 2, 3]);
  });

  it('joins unquoted words into a single todo', () => {
    const result = todo('add', 'Buy', 'groceries', 'today');
    assert.equal(result.code, 0);
    assert.equal(readTodos()[0].text, 'Buy groceries today');
  });

  it('trims surrounding whitespace', () => {
    todo('add', '   Buy groceries   ');
    assert.equal(readTodos()[0].text, 'Buy groceries');
  });

  it('preserves quotes, unicode, and shell-special characters', () => {
    const text = `Call "Mom" & Dad's café — $5 🎉`;
    assert.equal(todo('add', text).code, 0);
    assert.equal(readTodos()[0].text, text);
    assert.equal(todo('list').stdout, `1. [ ] ${text}\n`);
  });

  it('treats flag-like text as todo text', () => {
    assert.equal(todo('add', '--help').code, 0);
    assert.equal(readTodos()[0].text, '--help');
  });

  it('fails with usage when text is missing, without creating todos.json', () => {
    assertFailsWithoutChanges(['add'], /Missing todo text[\s\S]*Usage: node index\.js add/);
    assert.ok(!fs.existsSync(todosFile));
  });

  it('fails for empty or whitespace-only text', () => {
    assertFailsWithoutChanges(['add', ''], /cannot be empty/);
    assertFailsWithoutChanges(['add', '   '], /cannot be empty/);
    todo('add', 'existing');
    assertFailsWithoutChanges(['add', '\t'], /cannot be empty/);
  });
});

describe('list', () => {
  it('shows a friendly message when there are no todos', () => {
    const result = todo('list');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /No todos yet/);
    assert.equal(result.stderr, '');
  });

  it('does not create todos.json', () => {
    todo('list');
    assert.ok(!fs.existsSync(todosFile));
  });

  it('shows the empty message when todos.json is an empty array or empty file', () => {
    writeTodos([]);
    assert.match(todo('list').stdout, /No todos yet/);
    fs.writeFileSync(todosFile, '');
    assert.match(todo('list').stdout, /No todos yet/);
  });

  it('shows the empty message after every todo is deleted', () => {
    todo('add', 'a');
    todo('delete', '1');
    assert.match(todo('list').stdout, /No todos yet/);
  });

  it('shows id, status indicator, and text for every todo in order', () => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
    todo('add', 'Write report');
    todo('complete', '2');

    const result = todo('list');
    assert.equal(result.code, 0);
    assert.equal(
      result.stdout,
      '1. [ ] Buy groceries\n2. [x] Walk the dog\n3. [ ] Write report\n',
    );
  });

  it('aligns the status column once ids reach two digits', () => {
    for (let i = 1; i <= 10; i++) todo('add', `task ${i}`);
    const lines = todo('list').stdout.trimEnd().split('\n');
    assert.equal(lines.length, 10);
    assert.equal(lines[0], ' 1. [ ] task 1');
    assert.equal(lines[9], '10. [ ] task 10');
  });

  it('ignores extra arguments', () => {
    todo('add', 'a');
    assert.equal(todo('list', 'extra').stdout, '1. [ ] a\n');
  });
});

describe('complete', () => {
  beforeEach(() => {
    todo('add', 'Buy groceries');
    todo('add', 'Walk the dog');
  });

  it('marks a todo as done and leaves others pending', () => {
    const result = todo('complete', '1');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Completed todo #1: Buy groceries\n');
    assert.deepEqual(readTodos().map((t) => t.completed), [true, false]);
  });

  it('preserves the other fields of the completed todo', () => {
    const before = readTodos()[0];
    todo('complete', '1');
    assert.deepEqual(readTodos()[0], { ...before, completed: true });
  });

  it('succeeds with a notice when the todo is already done', () => {
    todo('complete', '1');
    const before = fs.readFileSync(todosFile, 'utf8');
    const result = todo('complete', '1');
    assert.equal(result.code, 0);
    assert.match(result.stdout, /already completed/);
    assert.equal(fs.readFileSync(todosFile, 'utf8'), before);
  });

  it('fails with usage when the id is missing', () => {
    assertFailsWithoutChanges(['complete'], /Missing todo id[\s\S]*Usage: node index\.js complete <id>/);
  });

  for (const id of ['abc', '0', '-1', '1.5', '1e1', '']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      assertFailsWithoutChanges(['complete', id], /Invalid id/);
