  });

  it('fails with usage when the id is missing', () => {
    assertFailsWithoutChanges(['delete'], /Missing todo id[\s\S]*Usage: node index\.js delete <id>/);
  });

  for (const id of ['abc', '0', '-1', '2.0', ' 2']) {
    it(`fails for invalid id ${JSON.stringify(id)}`, () => {
      assertFailsWithoutChanges(['delete', id], /Invalid id/);
    });
  }

  it('fails for an id that does not exist', () => {
    assertFailsWithoutChanges(['delete', '42'], /No todo with id 42/);
